peg'rule'Hex =
  PegRt.nomemo "Hex"
    (PegRt.choice
      [ do { PegRt.cls [('0', '9'), ('a', 'f'), ('A', 'F')] "[0-9a-fA-F]"
          ; PegPrelude.pure ()
          }
      ])

